   [168]={next_id=169, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="然后我才知道了这个小部落……坐落在雨林深处，居民全年靠狩猎和采摘为生。", msg_color="", msg_size=0, talker="伊芙特", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3504", 0, 0, -22, 205}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [169]={next_id=170, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="加上这个部落妇女儿童居多，极少数可以耕种的土地都被其他部落占据，一到雨季，就会失去所有的谋生手段，陷入缺衣少食的困窘。", msg_color="", msg_size=0, talker="伊芙特", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3504", 0, 0, -22, 205}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [170]={next_id=171, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="当时成立的基金会本来就是为了帮助雨林居民嘛，于是我立刻去了基金会驻地，拿了一些食物和衣服应急。", msg_color="", msg_size=0, talker="伊芙特", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3504", 0, 0, -22, 205}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [171]={next_id=172, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我听这边的人说，这片区域像这样的微型部落尤其多，因为远离城区，雨林环境又很恶劣，塞洛维政府很难真正帮到这边。", msg_color="", msg_size=0, talker="伊芙特", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3504", 0, 0, -22, 205}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
